"""Buildless dashboard served by FastAPI; browser assets stay together here."""

PAGE = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#f5f5ee"><title>Visual Second Brain</title>
<style>
:root{--paper:#f5f5ee;--panel:#fffefa;--ink:#25342c;--muted:#687168;--line:#dce0d5;--green:#335c41;--soft:#e9eedf;--accent:#d7e98c;--red:#a33d30;--radius:18px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;color:var(--ink);background:var(--paper)}
*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button,a,input,textarea,select{outline-offset:4px}button{cursor:pointer;border:1px solid var(--line);border-radius:9px;padding:10px 15px;background:var(--panel);color:var(--ink);font-weight:600}button:hover{border-color:var(--green);background:var(--soft)}button:disabled{opacity:.55;cursor:wait}a{color:var(--green)}input,textarea,select{width:100%;border:1px solid var(--line);background:var(--panel);border-radius:9px;padding:10px;color:var(--ink)}textarea{resize:vertical;min-height:78px}label{display:block;font-size:12px;font-weight:650;margin-bottom:6px}.field{margin-bottom:14px}h1,h2,h3,p{margin:0}h1{font-size:clamp(30px,4vw,43px);letter-spacing:-1.6px;font-weight:550;line-height:1.15}h2{font-size:19px;letter-spacing:-.5px;font-weight:600}h3{font-size:15px}p{line-height:1.6}.muted{color:var(--muted);font-size:13px}.eyebrow{font-family:ui-monospace,monospace;text-transform:uppercase;font-size:10px;letter-spacing:1.4px;color:var(--muted)}.primary{background:var(--green);color:white;border-color:var(--green)}.primary:hover{background:#24482f;color:white}.small{font-size:12px;padding:7px 10px}.ghost{background:transparent}.row{display:flex;align-items:center;gap:10px}.between{justify-content:space-between}.wrap{flex-wrap:wrap}.stack{display:grid;gap:16px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.brand-mark{width:30px;height:30px;background:var(--green);color:var(--accent);display:grid;place-items:center;border-radius:9px;font-size:20px}.topbar{height:76px;max-width:1440px;margin:auto;padding:0 42px;border-bottom:1px solid var(--line)}.brand{font-size:14px;font-weight:700;letter-spacing:-.3px}.tag{font:10px ui-monospace,monospace;text-transform:uppercase;letter-spacing:.7px;background:var(--soft);padding:6px 9px;border-radius:6px;color:var(--green)}main{max-width:1440px;margin:auto;padding:38px 42px 60px}.intro{margin-bottom:30px;align-items:flex-end}.intro p{margin-top:12px}.date{font-size:12px;color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:25px}.stat{border:1px solid var(--line);padding:18px 21px;border-radius:12px;display:flex;align-items:center;justify-content:space-between;background:#ffffff60}.stat strong{font-weight:500;font-size:27px}.workspace{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(330px,.9fr);gap:24px;align-items:start}.panel{border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);overflow:hidden}.panel-head{padding:23px 24px;border-bottom:1px solid var(--line)}.panel-body{padding:22px 24px}.section-note{margin-top:6px}.task{padding:18px 22px;border-bottom:1px solid var(--line);transition:background .15s}.task:last-child{border-bottom:0}.task.selected{background:#eff3e8;border-left:3px solid var(--green);padding-left:19px}.task.child{margin-left:28px;border-left:1px solid var(--line)}.task-main{align-items:flex-start}.check{width:20px;height:20px;flex:none;margin:2px 0 0;accent-color:var(--green);cursor:pointer}.task-title{display:block;text-align:left;border:0;background:none;padding:0;font-weight:600;font-size:14px;line-height:1.5}.task-title:hover{background:transparent;text-decoration:underline}.task-title.done{text-decoration:line-through;color:var(--muted)}.task-copy{flex:1;min-width:0}.task-description{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:85px;overflow:auto;color:var(--muted);margin-top:5px}.meta{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:9px;font-size:10px;color:var(--muted)}.pill{border-radius:5px;padding:3px 6px;background:var(--soft);font-size:10px;color:var(--green)}.pill.high,.pill.very_high{background:#f1e8cd;color:#786022}.empty{padding:30px 24px;text-align:center;color:var(--muted)}.empty-symbol{font-size:31px;display:block;color:#8f9e7e;margin-bottom:12px}.empty p{font-size:13px;max-width:280px;margin:8px auto}.task-form{border-top:1px solid var(--line);padding:20px 24px;background:#fafbf5}.task-form summary{cursor:pointer;font-size:13px;font-weight:650}.task-form[open] summary{margin-bottom:18px}.focus{padding:18px;background:var(--soft);border-radius:12px;margin-bottom:18px}.focus h3{margin-top:7px;overflow-wrap:anywhere}.context{margin-top:24px}.reply{white-space:pre-wrap;font-size:13px;line-height:1.7;margin:14px 0;overflow-wrap:anywhere}.proposal{border:1px solid var(--line);padding:17px;border-radius:12px;margin-top:15px;background:#fbfcf7}.proposal-head{margin-bottom:15px}.proposal-step{padding-top:13px;border-top:1px solid var(--line);margin-top:13px}.proposal-step textarea{font-size:12px;min-height:58px;margin-top:7px}.proposal-step input{font-size:13px}.review-actions{margin-top:15px;display:flex;gap:9px}.activity{margin-top:22px}.activity-item{padding:12px 0;border-bottom:1px solid var(--line);font-size:12px}.activity-item:last-child{border:0}.dot{width:7px;height:7px;border-radius:50%;background:#8e9d83;display:inline-block;margin-right:8px}.dot.running{background:#c68a2b;animation:pulse 1.4s infinite}.dot.failed,.dot.stale{background:var(--red)}.history{max-height:240px;overflow:auto}.chat-message{font-size:12px;padding:11px 12px;margin:9px 0;background:var(--soft);border-radius:9px;white-space:pre-wrap;overflow-wrap:anywhere}.chat-message.user{background:var(--paper)}.chat-message small{display:block;color:var(--muted);font-size:10px;margin-bottom:5px}.error{border:1px solid #e2b8af;background:#fff1ed;color:#82372a;border-radius:10px;padding:14px 18px;margin-bottom:18px;font-size:13px;white-space:pre-wrap}.notice{font-size:12px;color:var(--green);min-height:20px;margin-bottom:12px}.pet{position:fixed;right:22px;bottom:20px;border-radius:50%;width:52px;height:52px;background:var(--green);color:var(--accent);box-shadow:0 5px 18px #23382a22;padding:0;font-size:24px;z-index:3}.pet:hover{background:#24482f;color:var(--accent)}dialog{background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:18px;padding:25px;max-width:500px;width:calc(100% - 32px)}dialog::backdrop{background:#15291b66}dialog h2{margin-bottom:22px}footer{margin-top:28px;font-size:11px;color:var(--muted)}[hidden]{display:none!important}@keyframes pulse{50%{opacity:.35}}@media(max-width:800px){.workspace{grid-template-columns:1fr}.topbar{padding:0 20px}main{padding:28px 20px}.intro{align-items:flex-start;gap:20px}.stats{gap:8px}.stat{padding:13px;display:block}.stat strong{display:block;margin-top:6px}.panel-head,.panel-body{padding:20px}.topbar .tag{display:none}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
</head>
<body>
<header class="topbar row between"><div class="row"><span class="brand-mark" aria-hidden="true">✳</span><span class="brand">Visual Second Brain</span><span class="tag">Your daily starting point</span></div><div class="row"><span class="muted">Personal demo</span><a href="/docs" class="muted">API docs ↗</a></div></header>
<main>
<div class="intro row between"><div><div class="eyebrow" id="today" style="margin-bottom:13px"></div><h1>A little clarity.<br>Room to get things done.</h1><p class="muted">Gather what matters, find a next step, and leave the rest here.</p></div><button id="refresh" class="small ghost">↻ Refresh</button></div>
<div id="error" class="error" role="alert" hidden></div><div id="notice" class="notice" role="status" aria-live="polite"></div>
<section id="access" class="panel" hidden style="margin-bottom:20px"><form id="access-form" class="panel-body"><h2>Demo access</h2><p class="muted section-note">Enter the demo access token configured for this app. This is separate from the Meta API key.</p><div class="row" style="margin-top:14px"><input id="token" type="password" aria-label="Demo access token" autocomplete="off" required><button class="primary">Connect</button></div></form></section>
<section class="stats" aria-label="Dashboard overview"><div class="stat"><span class="eyebrow">Open tasks</span><strong id="open-count">—</strong></div><div class="stat"><span class="eyebrow">Completed</span><strong id="done-count">—</strong></div><div class="stat"><span class="eyebrow">Plans to review</span><strong id="review-count">—</strong></div></section>
<div class="workspace">
<div class="stack">
<section class="panel"><div class="panel-head row between"><div><h2>On your mind</h2><p class="muted section-note">Your work, one manageable step at a time.</p></div><span class="tag">Tasks</span></div><div id="task-list" aria-live="polite"><div class="empty"><p>Loading your saved work…</p></div></div>
<details class="task-form" id="add-task" open><summary>＋ Add a task</summary><form id="task-form"><div class="field"><label for="task-title">What needs doing?</label><input id="task-title" name="title" placeholder="Finish my homework" maxlength="300" required></div><div class="field"><label for="task-description">Details Muse should know</label><textarea id="task-description" name="description" placeholder="The subject, assignment requirements, or where you’re stuck…" maxlength="10000"></textarea></div><div class="grid2"><div class="field"><label for="task-deadline">Due date · optional</label><input id="task-deadline" name="deadline" type="date"></div><div class="field"><label for="task-importance">Importance</label><select id="task-importance" name="importance" data-level-select></select></div></div><button type="submit" class="primary">Add to my day</button></form></details></section>
<section class="panel"><div class="panel-head"><h2>The bigger picture</h2><p class="muted section-note">Keep useful context here. Your edits inform the next plan.</p></div><form id="context-form" class="panel-body"><label for="context">What should Muse keep in mind?</label><textarea id="context" placeholder="I study part time. I can work on homework on Saturday mornings." maxlength="10000" required></textarea><div class="row between" style="margin-top:12px"><span class="muted" id="context-state">Not saved yet</span><button class="small" type="submit">Save context</button></div></form></section>
</div>
<aside class="stack" id="muse-panel">
<section class="panel"><div class="panel-head row between"><div class="row"><span class="brand-mark" aria-hidden="true">◕</span><div><h2>Make a little headway</h2><p class="muted">Plan with Muse</p></div></div><span class="tag">Review first</span></div><div class="panel-body"><div class="focus"><span class="eyebrow">Selected task</span><h3 id="selected-title">Choose a task to get started</h3><p class="muted" id="selected-hint" style="margin-top:6px">Add your first task, then ask Muse for a breakdown.</p></div><div id="conversation" class="history"></div><form id="plan-form"><label for="plan-message">How can Muse help?</label><textarea id="plan-message" maxlength="10000" required placeholder="Help me break this into a few clear steps."></textarea><div class="row between" style="margin-top:12px"><span class="muted">Suggestions wait for your approval.</span><button type="submit" class="primary" id="plan-button" disabled>Ask Muse ↗</button></div></form><div id="reviews"></div></div></section>
<section class="panel"><div class="panel-head"><h2>Planning activity</h2><p class="muted section-note">Actual requests and their outcomes.</p></div><div id="activity" class="panel-body"><p class="muted">No planning activity yet.</p></div></section>
</aside>
</div><footer>Saved work stays here between visits. Planning helps organize the work; completing it is up to you.</footer>
</main>
<button class="pet" id="pet" aria-label="Go to Muse planning" title="Plan with Muse">◕</button>
<dialog id="edit-dialog"><form id="edit-form"><div class="row between" style="margin-bottom:20px"><h2 style="margin:0">Edit task</h2><button type="button" id="close-edit" class="small" aria-label="Close editor">✕</button></div><input id="edit-id" type="hidden"><div class="field"><label for="edit-title">Task</label><input id="edit-title" required maxlength="300"></div><div class="field"><label for="edit-description">Details</label><textarea id="edit-description" maxlength="10000"></textarea></div><div class="grid2"><div class="field"><label for="edit-deadline">Due date</label><input id="edit-deadline" type="date"></div><div class="field"><label for="edit-importance">Importance</label><select id="edit-importance" data-level-select></select></div></div><div class="field"><label for="edit-status">Status</label><select id="edit-status"><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="completed">Completed</option></select></div><button class="primary" type="submit">Save changes</button></form></dialog>
<script>
'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={very_low:'Very low',low:'Low',medium:'Medium',high:'High',very_high:'Very high'};
let state={tasks:[],context:[],runs:[],messages:[]}, ranges={}, selected=localStorage.getItem('second-brain-selected'), token='', busy=false, editVersion=null, contextVersion=0, pendingRequest=null;
const drafts=new Map();
$('#today').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});
document.querySelectorAll('[data-level-select]').forEach(el=>{el.innerHTML='<option value="">Let Muse assess</option>'+Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');});
function level(task){return task.user_importance_level||Object.keys(ranges).find(k=>task.importance_score!==null&&task.importance_score>=ranges[k].min&&task.importance_score<=ranges[k].max)||'';}
function badge(task){const k=level(task);return `<span class="pill ${esc(k)}">${esc(labels[k]||'Unassessed')}</span>`;}
function showError(e){$('#error').textContent=e.message||'Something went wrong. Your drafts are still here.';$('#error').hidden=false;}
async function api(path,method='GET',body){let response;try{response=await fetch(path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});}catch{throw Error('Could not reach the server. Your draft is preserved; try again.');}const data=await response.json();if(!response.ok){if(response.status===401)$('#access').hidden=false;const fields=data.error?.fields?.map(f=>`${f.path.slice(1).join('.')}: ${f.message}`).join('\n');throw Error((data.error?.message||'Request failed')+(fields?'\n'+fields:'')+(response.status===409?' Refresh to get the latest saved state.':''));}return data;}
function setBusy(value){busy=value;document.querySelectorAll('button,input,textarea,select').forEach(b=>b.disabled=value);$('#plan-button').disabled=value||!state.tasks.some(t=>t.id===selected);}
async function action(work,success){if(busy)return;setBusy(true);$('#error').hidden=true;$('#notice').textContent='';try{await work();if(success)$('#notice').textContent=success;await refresh(false);}catch(e){showError(e);}finally{setBusy(false);}}
async function refresh(clear=true){if(clear){$('#error').hidden=true;$('#notice').textContent='';}const [data,levels]=await Promise.all([api('/api/dashboard'),api('/api/importance-levels')]);state=data;ranges=levels;$('#access').hidden=true;if(!state.tasks.some(t=>t.id===selected)){selected=state.tasks.find(t=>!t.parent_task_id&&t.status!=='completed')?.id||state.tasks[0]?.id||null;}localStorage.setItem('second-brain-selected',selected||'');render();}
function render(){
 $('#open-count').textContent=state.tasks.filter(t=>t.status!=='completed').length;$('#done-count').textContent=state.tasks.filter(t=>t.status==='completed').length;$('#review-count').textContent=state.runs.filter(r=>r.status==='awaiting_review').length;
 const taskHTML=(t,depth=0)=>{const children=state.tasks.filter(c=>c.parent_task_id===t.id).sort((a,b)=>a.position-b.position);return `<div class="task ${t.id===selected?'selected ':''}${depth?'child':''}"><div class="row task-main"><input class="check" type="checkbox" data-complete="${t.id}" aria-label="Mark ${esc(t.title)} ${t.status==='completed'?'pending':'complete'}" ${t.status==='completed'?'checked':''}><div class="task-copy"><button class="task-title ${t.status==='completed'?'done':''}" data-select="${t.id}">${esc(t.title)}</button>${t.description?`<p class="task-description">${esc(t.description)}</p>`:''}<div class="meta">${badge(t)}${t.deadline?`<span>Due ${esc(new Date(t.deadline+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</span>`:''}${t.status==='in_progress'?'<span>In progress</span>':''}${children.length?`<span>${children.filter(c=>c.status==='completed').length}/${children.length} steps</span>`:''}</div></div><button class="small ghost" data-edit="${t.id}" aria-label="Edit ${esc(t.title)}">Edit</button></div></div>`+children.map(c=>taskHTML(c,depth+1)).join('');};
 $('#task-list').innerHTML=state.tasks.length?state.tasks.filter(t=>!t.parent_task_id).map(t=>taskHTML(t)).join(''):'<div class="empty"><span class="empty-symbol">✳</span><h3>A clear place to start.</h3><p>Add something on your mind. A title is enough to begin.</p></div>';
 const task=state.tasks.find(t=>t.id===selected);$('#selected-title').textContent=task?.title||'Choose a task to get started';$('#selected-hint').textContent=task?'Select another task by clicking its title.':'Add your first task, then ask Muse for a breakdown.';$('#plan-button').disabled=busy||!task;
 const runIds=new Set(state.runs.filter(r=>r.task_id===selected).map(r=>r.id));$('#conversation').innerHTML=state.messages.filter(m=>runIds.has(m.run_id)).slice(-6).map(m=>`<div class="chat-message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'YOU':'MUSE'}</small>${esc(m.content)}</div>`).join('');
 const reviewRuns=state.runs.filter(r=>r.task_id===selected&&r.status==='awaiting_review');
 $('#reviews').innerHTML=reviewRuns.map(r=>{if(!drafts.has(r.id))drafts.set(r.id,structuredClone(r.proposal));const p=drafts.get(r.id);return `<section class="proposal" data-run="${r.id}"><div class="proposal-head"><div class="row between"><h3>Ready for your review</h3>${badge(p)}</div><p class="muted section-note">${p.subtasks.length?'Edit the steps below before adding them.':'Muse needs more detail. You can reply above, or save just the importance assessment.'}</p></div>${p.subtasks.map((s,i)=>`<div class="proposal-step" data-step="${i}"><div class="row between" style="margin-bottom:8px"><label for="proposal-${r.id}-${i}" style="margin:0">Step ${i+1}</label><button class="small ghost" data-remove="${r.id}" data-index="${i}">Remove</button></div><input id="proposal-${r.id}-${i}" data-proposal-title="${i}" maxlength="300" value="${esc(s.title)}" aria-label="Step ${i+1} title"><textarea data-proposal-description="${i}" maxlength="10000" aria-label="Step ${i+1} details">${esc(s.description)}</textarea></div>`).join('')}<div class="review-actions"><button class="primary small" data-approve="${r.id}">Save ${p.subtasks.length?'reviewed plan':'assessment'}</button><button class="small" data-reject="${r.id}">Reject</button></div></section>`;}).join('');
 const statuses={running:'Planning with Muse…',awaiting_review:'Waiting for your review',applied:'Reviewed plan saved',rejected:'Suggestion rejected',stale:'State changed · request a fresh plan',failed:'Planning failed · try again'};
 $('#activity').innerHTML=state.runs.length?[...state.runs].reverse().slice(0,8).map(r=>`<div class="activity-item"><div><span class="dot ${esc(r.status)}"></span>${esc(statuses[r.status]||r.status)}</div><p class="muted" style="margin:5px 0 0 15px">${esc(state.tasks.find(t=>t.id===r.task_id)?.title||'Task')}</p>${r.error?`<p class="muted" style="margin-left:15px">${esc(r.error)}</p>`:''}</div>`).join(''):'<p class="muted">No planning activity yet. Ask Muse when you’re ready.</p>';
 const ctx=state.context.find(c=>c.id==='daily-context');if(!$('#context').dataset.dirty){$('#context').value=ctx?.content||'';contextVersion=ctx?.version||0;}$('#context-state').textContent=$('#context').dataset.dirty?'Unsaved changes':ctx?'Saved for your next visit':'Not saved yet';
}
$('#task-form').onsubmit=e=>{e.preventDefault();const body={title:$('#task-title').value,description:$('#task-description').value,deadline:$('#task-deadline').value||null,user_importance_level:$('#task-importance').value||null};action(async()=>{const t=await api('/api/tasks','POST',body);selected=t.id;e.target.reset();},'Task saved. Ask Muse for a breakdown when you’re ready.');};
$('#task-list').onclick=e=>{const select=e.target.closest('[data-select]'),edit=e.target.closest('[data-edit]');if(select&&!busy){selected=select.dataset.select;localStorage.setItem('second-brain-selected',selected);render();}if(edit&&!busy){const t=state.tasks.find(t=>t.id===edit.dataset.edit);editVersion=t.version;$('#edit-id').value=t.id;$('#edit-title').value=t.title;$('#edit-description').value=t.description;$('#edit-deadline').value=t.deadline||'';$('#edit-importance').value=t.user_importance_level||'';$('#edit-status').value=t.status;$('#edit-dialog').showModal();}};
$('#task-list').onchange=e=>{const el=e.target.closest('[data-complete]');if(!el)return;const t=state.tasks.find(t=>t.id===el.dataset.complete),value=el.checked;el.checked=t.status==='completed';action(()=>api('/api/tasks/'+t.id,'PATCH',{expected_version:t.version,status:value?'completed':'pending'}),'Task updated.');};
$('#edit-form').onsubmit=e=>{e.preventDefault();action(async()=>{await api('/api/tasks/'+$('#edit-id').value,'PATCH',{expected_version:editVersion,title:$('#edit-title').value,description:$('#edit-description').value,deadline:$('#edit-deadline').value||null,user_importance_level:$('#edit-importance').value||null,status:$('#edit-status').value});$('#edit-dialog').close();},'Your changes are saved.');};$('#close-edit').onclick=()=>$('#edit-dialog').close();
$('#context').oninput=()=>{$('#context').dataset.dirty='true';$('#context-state').textContent='Unsaved changes';};
$('#context-form').onsubmit=e=>{e.preventDefault();const content=$('#context').value;action(async()=>{const saved=await api('/api/context/daily-context','PUT',{expected_version:contextVersion,category:'current_situation',content,provenance:'user_stated'});contextVersion=saved.version;if($('#context').value===content)delete $('#context').dataset.dirty;},'Context saved. Future plans will use your correction.');};
$('#plan-form').onsubmit=e=>{e.preventDefault();const message=$('#plan-message').value;if(!selected)return;if(!pendingRequest||pendingRequest.task!==selected||pendingRequest.message!==message)pendingRequest={task:selected,message,id:crypto.randomUUID()};const request=pendingRequest;action(async()=>{$('#plan-button').textContent='Planning…';try{const run=await api('/api/tasks/'+request.task+'/plans','POST',{request_id:request.id,message});if(run.status==='running')throw Error('Muse is still planning. Refresh to check activity, or retry this same request.');pendingRequest=null;if(run.status==='failed')throw Error(run.error||'Planning failed. Try again.');if(run.status==='stale')throw Error('Your state changed during planning. Request a fresh plan.');if($('#plan-message').value===message)$('#plan-message').value='';}finally{$('#plan-button').textContent='Ask Muse ↗';await refresh(false);}},'Muse replied. Review any suggestions before saving.');};
$('#reviews').oninput=e=>{const section=e.target.closest('[data-run]');if(!section)return;const p=drafts.get(section.dataset.run);if(e.target.dataset.proposalTitle!==undefined)p.subtasks[+e.target.dataset.proposalTitle].title=e.target.value;if(e.target.dataset.proposalDescription!==undefined)p.subtasks[+e.target.dataset.proposalDescription].description=e.target.value;};
$('#reviews').onclick=e=>{const approve=e.target.closest('[data-approve]'),reject=e.target.closest('[data-reject]'),remove=e.target.closest('[data-remove]');if(busy)return;if(remove){drafts.get(remove.dataset.remove).subtasks.splice(+remove.dataset.index,1);render();}if(approve){const id=approve.dataset.approve,p=drafts.get(id);if(p.subtasks.some(s=>!s.title.trim())){showError(Error('Give each proposed step a title before saving.'));return;}action(()=>api('/api/runs/'+id+'/approve','POST',{proposal:p}),'Reviewed plan saved to your tasks.');}if(reject)action(()=>api('/api/runs/'+reject.dataset.reject+'/reject','POST'),'Suggestion rejected. Your tasks are unchanged.');};
$('#refresh').onclick=()=>action(async()=>{},'Saved state refreshed.');$('#access-form').onsubmit=e=>{e.preventDefault();token=$('#token').value;$('#token').value='';action(async()=>{},'Connected to your demo.');};$('#pet').onclick=()=>{$('#muse-panel').scrollIntoView({behavior:'smooth'});$('#plan-message').focus({preventScroll:true});};
refresh().catch(showError);
// Only poll during an actual provider request; leave review edits intact.
setInterval(()=>{if(busy&&pendingRequest)api('/api/dashboard').then(data=>{state=data;const running=data.runs.some(r=>r.status==='running');if(running)$('#notice').textContent='Muse is planning. Your task is still awaiting your review.';}).catch(()=>{});},4000);
</script></body></html>"""
